/**
 * Finds a folder's git directory, its current branch, and the shas refs point
 * at by reading `.git`, `HEAD`, the ref files, and `packed-refs` directly. No
 * git process starts here, so a repository's config, hooks, or fsmonitor can
 * never run code because the branch was drawn. The batch segment's narrow
 * exception, which does run git, is recorded in docs/notes.md.
 */

/** The file reads gitinfo needs, so tests can stand in for a disk. */
export type GitFs = {
  /** `'file'`, `'dir'`, or `'other'`; null when the path does not exist. */
  kind: (path: string) => Promise<'file' | 'dir' | 'other' | null>
  /** The file's text; null when it cannot be read. */
  read: (path: string) => Promise<string | null>
}

/** A repository found from a folder: its git directory and the work tree that holds `.git`. */
export type Repo = { gitDir: string; workTree: string }

/** What HEAD names: a branch, with a null sha while the branch has no commit yet, or a detached commit. */
export type Head =
  | {
      kind: 'branch'
      /** The full ref name, for example `refs/heads/dev`. */
      ref: string
      sha: string | null
    }
  | { kind: 'detached'; sha: string }

/** A full SHA-1 or SHA-256 object id, in git's lowercase hex. */
export const FULL_SHA = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/

const MAX_HEAD_CHARS = 512
const MAX_BRANCH_CHARS = 32
const MAX_REF_CHARS = 256
const BRANCH_PREFIX = 'refs/heads/'
// Characters git never allows in a ref name, plus the separators that could
// turn a name read from HEAD into a path outside the git directory.
const REF_FORBIDDEN = /[\x00-\x20\x7f~^:?*[\\]/

/** Normalizes a path to forward slashes without a trailing separator. */
export function slashPath(p: string): string {
  const s = p.replaceAll('\\', '/')
  return s.length > 1 && s.endsWith('/') && !/^[A-Za-z]:\/$/.test(s) ? s.replace(/\/+$/, '') : s
}

function parent(p: string): string {
  const i = p.lastIndexOf('/')
  if (i < 0) return p
  if (i === 0) return '/'
  if (/^[A-Za-z]:$/.test(p.slice(0, i))) return p.slice(0, i + 1)
  return p.slice(0, i)
}

const join = (dir: string, name: string) => (dir.endsWith('/') ? dir + name : `${dir}/${name}`)
const isAbsolute = (p: string) => p.startsWith('/') || /^[A-Za-z]:\//.test(p)

// Joins a relative path onto `dir`, folding `.` and `..` segments.
function resolvePath(dir: string, rel: string): string {
  let out = dir
  for (const part of rel.split('/')) {
    if (part === '' || part === '.') continue
    out = part === '..' ? parent(out) : join(out, part)
  }
  return out
}

async function firstLine(fs: GitFs, path: string): Promise<string | null> {
  const text = await fs.read(path)
  if (text === null) return null
  return text.slice(0, MAX_HEAD_CHARS).split('\n')[0].replace(/\r$/, '')
}

function isRefName(name: string): boolean {
  return (
    name.length <= MAX_REF_CHARS &&
    name.startsWith('refs/') &&
    !name.endsWith('/') &&
    !name.includes('..') &&
    !name.includes('//') &&
    !REF_FORBIDDEN.test(name)
  )
}

// HEAD's first line as the ref it names or the commit it holds.
function parseHead(line: string): { ref: string } | { sha: string } | null {
  const ref = /^ref:\s*(.+)$/.exec(line)
  if (ref) return { ref: ref[1].trim() }
  const sha = line.trim()
  return /^[0-9a-f]{40,64}$/.test(sha) ? { sha } : null
}

/**
 * Finds the repository holding `dir`, walking up to the filesystem root. In a
 * worktree or submodule, `.git` is a file that holds `gitdir: <path>`.
 *
 * @returns The repository, or null outside one.
 */
export async function findRepo(fs: GitFs, dir: string): Promise<Repo | null> {
  let current = slashPath(dir)
  for (;;) {
    const dotGit = join(current, '.git')
    const kind = await fs.kind(dotGit)
    if (kind === 'dir') return { gitDir: dotGit, workTree: current }
    if (kind === 'file') {
      const line = await firstLine(fs, dotGit)
      if (line === null || !line.startsWith('gitdir:')) return null
      const target = slashPath(line.slice('gitdir:'.length).trim())
      if (target === '') return null
      return { gitDir: isAbsolute(target) ? target : join(current, target), workTree: current }
    }
    const up = parent(current)
    if (up === current) return null
    current = up
  }
}

/**
 * Returns the branch checked out in `gitDir`, `detached <sha7>`, or `''`.
 * The result is raw repository data: clean it before drawing it.
 */
export async function branchIn(fs: GitFs, gitDir: string): Promise<string> {
  if (gitDir === '') return ''
  const line = await firstLine(fs, join(gitDir, 'HEAD'))
  const head = line === null ? null : parseHead(line)
  if (head === null) return ''
  if ('sha' in head) return `detached ${head.sha.slice(0, 7)}`
  if (!head.ref.startsWith(BRANCH_PREFIX)) return ''
  const branch = [...head.ref.slice(BRANCH_PREFIX.length).trim()]
  return branch.length > MAX_BRANCH_CHARS
    ? branch.slice(0, MAX_BRANCH_CHARS - 1).join('') + '\u2026'
    : branch.join('')
}

/**
 * Gets the common git directory: `gitDir` itself, or, in a linked worktree,
 * where its `commondir` file points. Branches, remotes, and `packed-refs` live
 * there; `HEAD` stays in `gitDir`.
 */
export async function commonDir(fs: GitFs, gitDir: string): Promise<string> {
  const line = await firstLine(fs, join(gitDir, 'commondir'))
  const target = slashPath(line?.trim() ?? '')
  if (target === '') return gitDir
  return isAbsolute(target) ? target : resolvePath(gitDir, target)
}

/**
 * Resolves a full ref name to its sha from the ref's loose file in the common
 * git directory, falling back to that directory's `packed-refs`, as git does.
 *
 * @param refName - The full ref name, for example `refs/remotes/origin/main`. A
 *     name git would refuse, or one that could lead outside the git directory,
 *     resolves to null without a read.
 * @returns The sha, or null when neither file names the ref.
 */
export async function resolveRef(fs: GitFs, gitDir: string, refName: string): Promise<string | null> {
  if (gitDir === '' || !isRefName(refName)) return null
  const common = await commonDir(fs, gitDir)
  const loose = (await fs.read(join(common, refName)))?.trim() ?? ''
  if (FULL_SHA.test(loose)) return loose
  const packed = await fs.read(join(common, 'packed-refs'))
  if (packed === null) return null
  for (const lineText of packed.split('\n')) {
    const [sha, name] = lineText.trim().split(' ')
    if (name === refName && FULL_SHA.test(sha)) return sha
  }
  return null
}

/**
 * Reads what HEAD names in `gitDir`, and the sha of the branch it names.
 *
 * @returns The head, or null when HEAD is missing, unreadable, or names
 *     something other than a valid branch under `refs/heads/` or a full sha.
 */
export async function readHead(fs: GitFs, gitDir: string): Promise<Head | null> {
  if (gitDir === '') return null
  const line = await firstLine(fs, join(gitDir, 'HEAD'))
  const head = line === null ? null : parseHead(line)
  if (head === null) return null
  if ('sha' in head) return FULL_SHA.test(head.sha) ? { kind: 'detached', sha: head.sha } : null
  if (!head.ref.startsWith(BRANCH_PREFIX) || !isRefName(head.ref)) return null
  return { kind: 'branch', ref: head.ref, sha: await resolveRef(fs, gitDir, head.ref) }
}

files.src/live.ts:
/**
 * Turns what a session reports through the mods API into the line.
 *
 * The Go paceline reads the status JSON Claude Code pipes to it; a mod asks
 * the session instead. These functions turn those answers into the same
 * payload shape, so render.ts runs unchanged against the parity fixtures and
 * live. The calls on `$` themselves live in hooks/register.ts, because the
 * engine only follows `$` within the hooks module.
 */

import type { SessionRateLimit, SessionUsage } from 'claude-code'

import type { BatchState } from './batch.ts'
import type { Config } from './config.ts'
import { explainForecast, type Activity, type ForecastTrace } from './forecast.ts'
import type { LoopFile } from './loop.ts'
import { modelName } from './model.ts'
import { isValidSnapshot, type Snapshot } from './pace.ts'
import type { Limit, Payload } from './payload.ts'
import type { Run } from './progress.ts'
import { render, type Line, type LimitPick } from './render.ts'

/** Where this mod keeps today's budget snapshot in its `$.store`. */
export const SNAPSHOT_KEY = 'day'
/**
 * Where this mod keeps its record of active hours, for the forecast. Builds
 * before 0.4.1 used `activity` and counted an idle session's older reading
 * as use; they may still be running, so this build leaves that key to them
 * and keeps its own.
 */
export const ACTIVITY_KEY = 'activity-v2'
/** The key builds before 0.4.1 wrote, read once to carry the hour history over. */
export const LEGACY_ACTIVITY_KEY = 'activity'

/** What the session reported for one refresh. */
export type Figures = {
  usage: SessionUsage
  modelId: string
  cwd: string
  root: string
  sessionId: string
  nowMs: number
  settings: Readonly<Record<string, unknown>>
  /** The effort level of the latest turn, from a classic hook event. */
  effort?: string
}

/** Claude Code's config directory, honoring CLAUDE_CONFIG_DIR. */
export function configDirFrom(env: {
  claudeConfigDir?: string
  userProfile?: string
  home?: string
}): string {
  const slash = (p: string) => p.replaceAll('\\', '/').replace(/\/+$/, '')
  if (env.claudeConfigDir) return slash(env.claudeConfigDir)
  // USERPROFILE first: on Windows, HOME can hold a Git Bash path like /c/Users/me.
  const home = env.userProfile || env.home
  return home ? `${slash(home)}/.claude` : '.claude'
}

/** One rate-limit window in the payload's shape: epoch seconds for the reset. */
export function toLimit(r: SessionRateLimit | undefined): Limit | undefined {
  if (!r) return undefined
  const resetsMs = r.resetsAt === undefined ? NaN : Date.parse(r.resetsAt)
  return {
    usedPercentage: r.percentUsed,
    resetsAt: Number.isFinite(resetsMs) ? Math.floor(resetsMs / 1000) : undefined,
  }
}

/** Builds the status payload from a session's figures. */
export function toPayload(f: Figures): Payload {
  const configured = f.settings.effortLevel
  const effort = f.effort ?? (typeof configured === 'string' ? configured : '')
  return {
    model: { displayName: modelName(f.modelId) },
    effort: effort ? { level: effort } : undefined,
    fastMode: f.settings.fastMode === true,
    cwd: f.cwd,
    sessionId: f.sessionId,
    workspace: { currentDir: f.cwd, projectDir: f.root },
    rateLimits: {
      fiveHour: toLimit(f.usage.rateLimits.find(r => r.kind === 'five_hour')),
      sevenDay: toLimit(f.usage.rateLimits.find(r => r.kind === 'seven_day')),
    },
    contextWindow: { usedPercentage: f.usage.context.percent },
    cost: { totalDurationMs: f.nowMs - f.usage.startedAt },
  }
}

function parseSnapshot(text: string | null): Snapshot | null {
  if (text === null) return null
  try {
    const value: unknown = JSON.parse(text)
    return isValidSnapshot(value) ? value : null
  } catch {
    return null
  }
}

/**
 * Picks today's snapshot. When the Go paceline has already anchored this same
 * day and week in paceline-day.json (`goText`), its anchor wins, so both lines
 * show the same budget. Otherwise the mod's own snapshot from `$.store`
 * (`stored`). The mod never writes the Go file.
 */
export function chooseSnapshot(
  goText: string | null,
  stored: unknown,
  today: string,
  week: Limit | undefined,
): Snapshot | null {
  const fromGo = parseSnapshot(goText)
  if (
    fromGo !== null &&
    fromGo.date === today &&
    fromGo.resetsAt === week?.resetsAt &&
    (week.usedPercentage ?? -1) >= fromGo.usedAtStart
  ) {
    return fromGo
  }
  return isValidSnapshot(stored) ? stored : null
}

/** Everything a live render reads besides the payload and config. */
export type LiveState = {
  snapshot: Snapshot | null
  branch: string
  run: Run | null
  /** The repository's `/orc-loop` state file, or null. */
  loop: LoopFile | null
  /** The repository's dev -> main review batch, or null when the segment doesn't apply or isn't known yet. */
  batch: BatchState | null
  activity: Activity | null
  nowMs: number
  /** The limit the forecast picked last time, so a near tie doesn't flip it. */
  previous?: LimitPick['show']
}

/**
 * The line in the compact layout, the limit the forecast picked, and the
 * snapshot to save when today's anchor changed. Unless the config asks for
 * both limits, the line warns only when the picked limit is forecast to run
 * out before it resets.
 */
export function renderLive(
  payload: Payload,
  config: Config,
  state: LiveState,
): { line: Line; pick: LimitPick | null; trace: ForecastTrace | null; save?: Snapshot } {
  const forecast =
    config.limits === 'auto'
      ? explainForecast({
          nowMs: state.nowMs,
          zone: 'local',
          session: payload.rateLimits?.fiveHour,
          week: payload.rateLimits?.sevenDay,
          activity: state.activity,
          weekAtDayStart: state.snapshot?.usedAtStart,
          previous: state.previous,
        })
      : null
  const pick = forecast?.pick ?? null
  const changed: { save?: Snapshot } = {}
  const line = render(payload, {
    nowMs: state.nowMs,
    zone: 'local',
    config,
    readSnapshot: () => state.snapshot,
    saveSnapshot: s => {
      changed.save = s
    },
    branch: () => state.branch,
    progress: () => state.run,
    loop: () => state.loop,
    batch: () => state.batch,
    compact: true,
    limits: pick ?? undefined,
  })
  return { line, pick, trace: forecast?.trace ?? null, ...changed }
}

/** What `debugReport` needs besides the render's own result. */
export type DebugInput = {
  nowMs: number
  payload: Payload
  config: Config
  state: LiveState
  /** Which source the day snapshot came from. */
  snapshotSource: 'go-file' | 'store' | 'none'
  result: { pick: LimitPick | null; trace: ForecastTrace | null }
}

/**
 * Everything behind the line's forecast as plain data, for the debug tool: the
 * readings, the day snapshot and where it came from, the stored activity, and
 * the forecast's own figures.
 */
export function debugReport(d: DebugInput) {
  const iso = (sec: number | undefined) => (sec === undefined ? undefined : new Date(sec * 1000).toISOString())
  const limit = (l: Limit | undefined) =>
    l && { usedPercentage: l.usedPercentage, resetsAt: iso(l.resetsAt), resetsAtEpoch: l.resetsAt }
  const pick = d.result.pick
  return {
    now: new Date(d.nowMs).toISOString(),
    utcOffsetMinutes: -new Date(d.nowMs).getTimezoneOffset(),
    limitsMode: d.config.limits,
    readings: {
      session: limit(d.payload.rateLimits?.fiveHour),
      week: limit(d.payload.rateLimits?.sevenDay),
    },
    daySnapshot: { source: d.snapshotSource, value: d.state.snapshot },
    activity: d.state.activity,
    previousPick: d.state.previous,
    pick: pick && { ...pick, outAtIso: iso(pick.outAt) },
    forecast: d.result.trace,
    note: d.result.trace
      ? undefined
      : 'No forecast: the config limits mode is not auto, or the session or week reading is missing.',
  }
}

files.src/loop.ts:
/**
 * Decodes an `/orc-loop` run's state file and draws it as the loop segment: one
 * cell per issue in the batch, then the run's phase.
 *
 * orc-loop writes the file to `<git dir>/orc-loop/state.json`. Everything in
 * it is untrusted: the decoder caps its size and the number of issues, keeps
 * only the fields the segment draws, and reduces the in-flight marker to an
 * issue number, so no string from the file reaches the line.
 */

import type { Segment, Span, Tone } from './render.ts'

/** The largest state file the decoder accepts, in bytes. */
export const MAX_STATE_BYTES = 256 * 1024
const MAX_ISSUES = 50
const MAX_REVIEW_ROUND = 99
const REVIEW_ROUNDS = 3

const MINUTE = 60 * 1000
const DONE_HIDDEN_AFTER = 30 * MINUTE
const PAUSED_AFTER = 6 * 60 * MINUTE

// The same glyphs as src/render.ts, copied rather than imported so that
// render.ts can import this module without the two loading each other.
// Importing only types from render.ts adds no such cycle.
const CELL_FULL = '\u25b0'
const CELL_EMPTY = '\u25b1'
const CHECK_MARK = '\u2713'

const PHASES = ['plan', 'build', 'review', 'triage', 'fallow', 'comments', 'done', 'halted'] as const
const STATUSES = ['pending', 'done', 'skipped', 'blocked'] as const
const PAUSABLE: readonly LoopPhase[] = ['build', 'review', 'plan']

// "44" or "#44": orc-loop writes the bare number while building, and a
// hand-edited or older file may carry the hash.
const ISSUE_REF = /^#?([1-9]\d{0,8})$/

/** A phase orc-loop writes, or `other` for one this version does not know. */
export type LoopPhase = (typeof PHASES)[number] | 'other'

/** An issue's status, or `other` for a missing or unknown one. */
export type IssueStatus = (typeof STATUSES)[number] | 'other'

/** One issue in the run's batch, as the segment draws it. */
export type LoopIssue = {
  /** The issue number, or null when the file's value is not one. */
  n: number | null
  status: IssueStatus
}

/** The parts of an orc-loop state file the segment draws. */
export type LoopState = {
  phase: LoopPhase
  issues: LoopIssue[]
  /** The issue being built, or null when the run is between issues or past the build. */
  inFlight: number | null
  /** The review round in progress; 0 before the first. */
  reviewRound: number
  /** True when the run draws its own bar through paceline's progress tools. */
  progressOn: boolean
}

/** A decoded state file and when it was last written, what {@link loopSegment} draws from. */
export type LoopFile = {
  state: LoopState
  /** The file's last write time, in epoch milliseconds. */
  mtimeMs: number
}

/** The state file inside a git directory. */
export function loopStatePath(gitDir: string): string {
  return `${gitDir}/orc-loop/state.json`
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

function oneOf<T extends string>(values: readonly T[], v: unknown): T | 'other' {
  return values.find(known => known === v) ?? 'other'
}

function issueNumber(v: unknown): number | null {
  if (typeof v === 'number') return Number.isSafeInteger(v) && v > 0 ? v : null
  if (typeof v !== 'string') return null
  const m = ISSUE_REF.exec(v)
  return m ? Number(m[1]) : null
}

function reviewRound(v: unknown): number {
  return typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= MAX_REVIEW_ROUND ? v : 0
}

function parseIssue(v: unknown): LoopIssue | null {
  if (!isRecord(v)) return null
  return { n: issueNumber(v.n), status: oneOf(STATUSES, v.status) }
}

/**
 * Decodes a state file's text, or returns null when it is oversized, not JSON,
 * has no string `phase`, or has an `issues` value that is not a list of up to
 * 50 objects. Missing optional fields take their empty values.
 */
export function decodeLoopState(fileText: string): LoopState | null {
  if (new TextEncoder().encode(fileText).length > MAX_STATE_BYTES) return null
  let doc: unknown
  try {
    doc = JSON.parse(fileText)
  } catch {
    return null
  }
  if (!isRecord(doc) || typeof doc.phase !== 'string') return null
  const issuesRaw = doc.issues ?? []
  if (!Array.isArray(issuesRaw) || issuesRaw.length > MAX_ISSUES) return null

  const issues: LoopIssue[] = []
  for (const raw of issuesRaw) {
    const issue = parseIssue(raw)
    if (issue === null) return null
    issues.push(issue)
  }
  return {
    phase: oneOf(PHASES, doc.phase),
    issues,
    inFlight: issueNumber(doc.inFlight),
    reviewRound: reviewRound(doc.reviewRound),
    progressOn: isRecord(doc.progress) && Boolean(doc.progress.on),
  }
}

// The same helper as in src/render.ts, copied for the reason given above CELL_FULL.
const span = (text: string, tone: Tone = 'plain'): Span => ({ text, tone })

function cell(issue: LoopIssue, inFlight: number | null): Span {
  if (issue.status === 'done') return span(CELL_FULL, 'green')
  if (issue.status === 'blocked') return span(CELL_FULL, 'red')
  if (issue.status === 'skipped') return span(CELL_FULL, 'dim')
  if (issue.n !== null && issue.n === inFlight) return span(CELL_FULL, 'cyan')
  return span(CELL_EMPTY, 'dim')
}

// Neighbors with the same glyph and tone share one span.
function cells(s: LoopState): Span[] {
  const out: Span[] = []
  for (const issue of s.issues) {
    const next = cell(issue, s.inFlight)
    const last = out.at(-1)
    if (last && last.tone === next.tone && last.text.startsWith(next.text)) last.text += next.text
    else out.push(next)
  }
  return out
}

function label(s: LoopState): Span {
  if (s.phase === 'halted') return span('halted', 'red')
  if (s.phase === 'done') return span(CHECK_MARK + ' done', 'green')
  if (s.phase === 'plan') return span('planning')
  if (s.phase === 'review') return span(`review ${Math.max(s.reviewRound, 1)}/${REVIEW_ROUNDS}`)
  const settled = s.issues.filter(i => i.status !== 'pending').length
  const current = s.inFlight === null ? '' : `#${s.inFlight} `
  return span(`${current}${settled}/${s.issues.length}`)
}

/**
 * Draws the run as "loop cells label", or returns null when it is hidden.
 *
 * The segment hides when there is no state, when the run draws its own bar
 * through paceline's progress tools, and once a finished run's file is over 30
 * minutes old. A build, review, or plan whose file has gone 6 hours without a
 * write gets a dim " (paused)" after its label.
 *
 * @param state - The decoded state file, or null when it is missing or unreadable.
 * @param mtimeMs - The state file's last write time, in epoch milliseconds.
 * @param nowMs - The current time, in epoch milliseconds.
 */
export function loopSegment(state: LoopState | null, mtimeMs: number, nowMs: number): Segment | null {
  if (state === null || state.progressOn) return null
  const age = nowMs - mtimeMs
  if (state.phase === 'done' && age > DONE_HIDDEN_AFTER) return null

  const out: Span[] = [span('loop'), span(' ')]
  const drawn = cells(state)
  if (drawn.length > 0) out.push(...drawn, span(' '))
  out.push(label(state))
  if (PAUSABLE.includes(state.phase) && age > PAUSED_AFTER) out.push(span(' (paused)', 'dim'))
  return out
}

